exec python3 -c 'exec('"'"'import sys,json,time,itertools\nfrom math import isqrt,gcd\np=55067263;v=(isqrt(8*p+1)-1)//2;c=p-v*(v+1)//2;k=v-c+1;K=k+1;B=4*K\ndef d(q,a):\n u=c//B**(2*q+a)%B;z=u//K;return u%K,z//2,2*(z%2)-1\nassert all(d(q,a)==(1-q,a,1-2*q) for q in (0,1) for a in (0,1))\ndef twice(q,h):\n for _ in range(2):q,a,m=d(q,0);h+=m\n return q,h\nassert all(twice(q,7)==(q,7) for q in (0,1)) and 1j*(-1j)==1\ndef E(g):return sum((i+1)**2*(((5^10^g)>>i)&1) for i in range(4))\nassert [g for g in range(16) if E(g)==0]==[15]\nb=open(sys.argv[1],"rb").read();G=1\nfor a in b:G=257*G+a+1\nz=G;r=[]\nwhile z>1:z,a=divmod(z,257);r.append(a-1)\nassert bytes(r[::-1])==b\nph=("dark","boundary","light","bubble","bubble","bubble","bubble","fusion","singularity","rebirth")\nlevels=(0,0,0,1,2,3,4,4,0,0)\narg=sys.argv[2] if len(sys.argv)>2 else "1";cycles=-1 if arg=="forever" else int(arg);assert cycles==-1 or cycles>0\nprint(json.dumps(dict(machine="LOGOS-COSMIC-42",p=p,transitions=4,U2=True,E257=True,bytes=len(b),c_lattice="1 cell/tick",oracle_zero="1111",model="symbolic, not physical or Akashic")))\nA=1\nfor t in itertools.count():\n if cycles>0 and t>=10*cycles:break\n j=t%10;s=ph[j];n=levels[j];w=1<<n if j not in (0,1,7,8) else 0\n a=2*n*(n+2);b=n*n+(n+2)**2;assert b*b-a*a==(4*(n+1))**2;g=gcd(a,b);beta=f"{a//g}/{b//g}"\n den=4*(n+1);g=gcd(b,den);gamma=f"{b//g}/{den//g}"\n A=257*A+j+1\n print(json.dumps(dict(t=t,phase=s,branch_entropy_bits=n,regions=w,beta=beta if j!=8 else None,gamma=gamma if j!=8 else None,index_span=[(1<<n)-1,(1<<(n+1))-2] if w else None,archive_bits=A.bit_length()),separators=(",",":")))\n if cycles==-1:time.sleep(.4)\n'"'"')' "$0" "$@"
